CONFIG = json.loads("{\"/reinigungsfirma-st-gallen/\":{\"name\":\"St. Gallen\",\"intro\":\"Reinigung für St. Gallen Stadt und den Kanton: Büros, Praxen, Läden, Mietliegenschaften und private Wohnungen können Sie bei uns anfragen. Wir planen einmalige und regelmässige Einsätze von unserem einzigen Standort Rorschach aus.\"},\"/reinigungsfirma-arbon/\":{\"name\":\"Arbon\",\"intro\":null},\"/reinigung-rheintal/\":{\"name\":\"das St. Galler Rheintal\",\"intro\":\"Reinigung für Altstätten, Heerbrugg und das weitere St. Galler Rheintal: für Büros, Praxen, Läden, Treppenhäuser, Wohnungen und Wohnungsabgaben sowie Fahrzeuge und Polster. Wir planen den Einsatz von Rorschach aus und bestätigen Umfang, Anfahrt und Termin persönlich.\"}}")
RHEINTAL_REPLACEMENTS = json.loads("{\"Autoinnenreinigung nach tatsächlichem Zustand\":\"Reinigungsaufträge in Altstätten und Heerbrugg planen\",\"Alltagsspuren sind etwas anderes als Tierhaare, starke Flecken oder Gerüche. Fotografieren Sie Sitze, Fussraum und Kofferraum separat und geben Sie Fahrzeuggrösse sowie Material an. Das Online-Paket beschreibt die enthaltenen Arbeiten am Standort Rorschach. Zusätzliche Tiefenreinigung, besondere Verschmutzung oder ein anderer Einsatzort benötigen eine persönliche Offerte. Aus Bildern entsteht keine automatische Diagnose oder Zusage zur Fleckenentfernung.\":\"Für wiederkehrende Firmen- und Verwaltungsaufträge benötigen wir Objektadresse, Flächen, bisherige Aufgaben und den gewünschten Rhythmus. Teilen Sie uns mit, ob Büro, Treppenhaus, Sanitärbereiche, Fenster oder weitere Arbeiten dazugehören. Bei einer Wohnungsabgabe nennen Sie zusätzlich den Übergabetermin. Wir stimmen Reinigungszeiten, Schlüsselübergabe und Anfahrt aus Rorschach ab und offerieren die vereinbarten Arbeiten mit Gesamtpreis.\",\"Ist Sitz-Tiefenreinigung automatisch enthalten?\":\"Kann ich die gesamte Reinigung meiner Liegenschaft anfragen?\",\"Massgeblich ist der angezeigte oder schriftlich angebotene Leistungsumfang. Ein zusätzliches Verfahren für Sitze wird vorab geprüft und separat vereinbart.\":\"Ja. Nennen Sie alle gewünschten Arbeiten, zum Beispiel Büro, Treppenhaus, Sanitärbereiche und Fenster, sowie den Rhythmus und Ihre Verbesserungswünsche. Wir prüfen die Aufgaben gemeinsam und halten den vereinbarten Gesamtumfang in einer Offerte fest.\"}")
def enhance_regional_services(document, path):
    if path not in BLOCKS:
        return document
    intro = CONFIG[path].get("intro")
    if intro:
        document = re.sub(r'(<section class="hero[\s\S]*?<p>)[\s\S]*?(</p>)', lambda m: m[1]+intro+m[2], document, count=1)
    replaced = False
    def section(m):
        nonlocal replaced
        if not replaced and ('class="service-grid"' in m[0] or (path == "/reinigung-rheintal/" and "Passende Leistungen" in m[0])):
            replaced = True
            return BLOCKS[path]
        return m[0]
    document = re.sub(r"<section\b[^>]*>[\s\S]*?</section>", section, document)
    if path == "/reinigung-rheintal/":
        for old, new in RHEINTAL_REPLACEMENTS.items():
            document = document.replace(old, new)
    if path == "/reinigungsfirma-st-gallen/":
        document = document.replace("Wohnungsreinigung, Umzugs- und Endreinigung mit vereinbarter Abgabegarantie, Autoinnenreinigung und Polsterreinigung.", "Wohnungs- und Endreinigung, Büro-, Treppenhaus- und Unterhaltsreinigung sowie Fenster-, Praxis-, Laden-, Auto- und Polsterreinigung. Weitere Innen- und Aussenreinigungen stimmen wir nach Bedarf ab.")
    return document
